// Parse & normalize the DrSnip custom-app INSURANCE payload (Train C).
// Shape comes from lib/n8n/payload.ts buildInsurancePayload — flatter than
// Registration (no medical history, no consents) and with two additions:
// `sex` (Registration does not collect it) and a nested primary/secondary
// carrier block.
//
// OUTPUT CONTRACT: the field names below are what `Disambiguate Patient`
// consumes (first_name / last_name / dob / email / phone_digits). That node is
// a VERBATIM copy of Registration v2's, so this parser must feed it exactly
// what Registration's parser feeds it. Do not rename these keys.
//
// NO CARD BYTES ever arrive here — only the non-PHI cards.hasCards / cards.count
// signal. Train D fetches the bytes from the app's internal service-token
// endpoints.
const raw = $input.first().json;
const body = raw.body || raw;

const patient = body.patient || {};
const insurance = body.insurance || {};
const primary = insurance.primary || {};
const secondary = insurance.secondary || null;
const cards = body.cards || {};

const phoneDigits = (patient.phone || '').replace(/\D/g, '');

function trimStr(v) { return typeof v === 'string' ? v.trim() : ''; }

// The insurance form marks street / city / state / ZIP required, so unlike
// Registration there is no freeform blob to parse. The sentinels below mirror
// Registration's Parse & Normalize purely as defence-in-depth for a malformed
// or replayed payload: DrChrono's create rejects a blank city/zip.
// NOTE (known, deliberate): DrChrono's UPDATE rejects the '00000' sentinel even
// though create accepts it (see verification-test-2026-07-20.md). Behaviour is
// identical to Registration here on purpose — this path is unreachable from the
// live form, and diverging from the proven node is the larger risk.
const city = trimStr(patient.city);
const zip = trimStr(patient.postalCode);
const finalCity = city || 'Unspecified';
const finalZip = zip || '00000';

return [{ json: {
  submission_id: body.submissionId || '',
  form_type: body.formType || 'insurance',
  timestamp: body.submittedAt || new Date().toISOString(),
  // Train E: pre-rendered clinic-local time from the app, so the staff
  // notification cannot silently render in UTC if this template is edited.
  submitted_at_pacific: body.submittedAtPacific || '',
  source: 'custom-app-insurance-v1',

  first_name: patient.firstName || '',
  last_name: patient.lastName || '',
  dob: patient.dateOfBirth || '',
  sex: patient.sex || '',
  email: (patient.email || '').toLowerCase().trim(),
  phone: patient.phone || '',
  phone_digits: phoneDigits,

  address_line1: trimStr(patient.streetAddress),
  address_line2: trimStr(patient.addressLine2),
  address_city: finalCity,
  address_state: trimStr(patient.state),
  address_zip: finalZip,
  address_country: trimStr(patient.country),
  address_city_sentinel: !city,
  address_zip_sentinel: !zip,

  office_location: patient.officeLocation || '',

  // Carrier data — carried for the audit row and for Train D's summary PDF.
  // NOT written to DrChrono in Train C (Registration sets no insurance fields
  // either; see FINDINGS-bridge-insurance.md OPEN QUESTION 3).
  primary_carrier: primary.carrier || '',
  primary_policy_no: primary.policyNo || '',
  primary_group_no: primary.groupNo || '',
  primary_relationship: primary.relationship || '',
  has_secondary: !!secondary,
  secondary_carrier: (secondary && secondary.carrier) || '',

  has_cards: cards.hasCards === true,
  card_count: cards.count || 0
}}];

// Tighter duplicate detection than the original Registration workflow.
// DrChrono returns candidates matching name + DOB. We then require email OR
// digit-only phone to also match before treating it as the same patient. If
// nothing passes, or multiple pass, we route to manual review instead of
// silently overwriting an unrelated record.
const searchResp = $input.first().json;
const candidates = (searchResp && searchResp.results) || [];
const original = $('Parse & Normalize').first().json;

const wantedEmail = (original.email || '').toLowerCase().trim();
const wantedPhone = original.phone_digits || '';
const normPhone = (p) => (p || '').replace(/\D/g, '');

const scored = candidates.map((c) => {
  const cEmail = (c.email || '').toLowerCase().trim();
  const cPhone = normPhone(c.cell_phone || c.home_phone || c.office_phone || '');
  const emailOk = !!wantedEmail && cEmail === wantedEmail;
  const phoneOk = !!wantedPhone && cPhone === wantedPhone;
  return { id: c.id, email_match: emailOk, phone_match: phoneOk, pass: emailOk || phoneOk };
});

let match_outcome, match_reason, patient_id = null;
const candidate_count = candidates.length;
const passing = scored.filter((s) => s.pass);
let candidates_summary = '';

if (candidate_count === 0) {
  match_outcome = 'create';
  match_reason = 'no_candidates_create_new';
} else if (passing.length === 1) {
  match_outcome = 'update';
  match_reason = 'unique_disambiguated_match';
  patient_id = passing[0].id;
} else if (passing.length === 0) {
  match_outcome = 'manual_review';
  match_reason = candidate_count === 1 ? 'single_candidate_failed_disambiguation' : 'no_candidate_passed_disambiguation';
  candidates_summary = scored.map((s) => 'id=' + s.id).join(';');
} else {
  match_outcome = 'manual_review';
  match_reason = 'multiple_candidates_passed_disambiguation';
  candidates_summary = passing.map((s) => 'id=' + s.id).join(';');
}

return [{ json: {
  ...original,
  candidates_searched: candidate_count,
  passing_count: passing.length,
  candidates_summary,
  match_outcome,
  match_reason,
  patient_id
}}];

// Merge DrChrono response (Create or Update) with the original normalized payload.
const drchrono = $input.first().json;
const original = $('Parse & Normalize').first().json;
const disambig = $('Disambiguate Patient').first().json;

let patient_id = null;
let drchrono_action = null;

if (disambig.match_outcome === 'update') {
  // Update path — DrChrono PATCH may return an empty body; fall back to the
  // patient_id we already disambiguated.
  patient_id = disambig.patient_id || drchrono.id || null;
  drchrono_action = 'updated';
} else if (disambig.match_outcome === 'create') {
  patient_id = drchrono.id || null;
  drchrono_action = 'created';
}

return [{ json: { ...original, patient_id, drchrono_action } }];

// Train D — fan the stored card list into one item per uploadable file.
// Input is the app's /api/internal/submission-files response (metadata only —
// the bytes are fetched one at a time by the next node, so no card image ever
// sits in this workflow's memory as a batch).
const resp = $input.first().json || {};
const files = resp.files || [];
const patient_id = $('Resolve Patient ID').first().json.patient_id;
const submission_id = $('Parse & Normalize').first().json.submission_id;

const SLOT = {
  insurance_front: 'primary front',
  insurance_back: 'primary back',
  partner_front: 'secondary front',
  partner_back: 'secondary back'
};

return files.map((f) => ({
  json: {
    file_id: f.id,
    kind: f.kind,
    slot_label: SLOT[f.kind] || f.kind,
    mime: f.mime,
    patient_id,
    submission_id
  }
}));

